const fs = require('node:fs');
const path = require('node:path');
const zlib = require('node:zlib');
const files = JSON.parse(zlib.gunzipSync(Buffer.from('', 'base64')).toString('utf8'));
for (const [name, content] of Object.entries(files)) {
  const destination = path.resolve(__dirname, name);
  if (!destination.startsWith(__dirname + path.sep)) throw Error('Invalid build path');
  fs.mkdirSync(path.dirname(destination), { recursive: true });
  fs.writeFileSync(destination, content);
}
console.log('Prepared standalone website and Netlify functions.');
